## Hooks核心原理

### 链表存储
Hooks通过链表存储在Fiber节点的memoizedState上。每次渲染按顺序调用Hooks，所以不能在条件/循环中调用。

```js
// Fiber节点
fiber.memoizedState = {
  memoizedState: stateValue,  // useState的值
  next: {                      // 下一个Hook
    memoizedState: effectObj,
    next: null
  }
}
```

// 简化版useState实现
let workInProgressHook = null;
let isMount = true;

function useState(initialValue) {
  let hook;
  if (isMount) {
    hook = { memoizedState: initialValue, queue: { pending: null }, next: null };
    if (!fiber.memoizedState) {
      fiber.memoizedState = hook;
    } else {
      workInProgressHook.next = hook;
    }
    workInProgressHook = hook;
  } else {
    hook = workInProgressHook;
    workInProgressHook = workInProgressHook.next;
  }

  // 处理更新队列
  let baseState = hook.memoizedState;
  if (hook.queue.pending) {
    let firstUpdate = hook.queue.pending.next;
    do {
      const action = firstUpdate.action;
      baseState = typeof action === 'function' ? action(baseState) : action;
      firstUpdate = firstUpdate.next;
    } while (firstUpdate !== hook.queue.pending.next);
    hook.queue.pending = null;
  }
  hook.memoizedState = baseState;
  return [baseState, dispatchAction.bind(null, hook.queue)];
}

// 闭包陷阱示例
function Counter() {
  const [count, setCount] = useState(0);

  // 错误：闭包捕获的是初始count
  useEffect(() => {
    const timer = setInterval(() => {
      setCount(count + 1); // count永远是0
    }, 1000);
    return () => clearInterval(timer);
  }, []); // 空依赖

  // 正确：使用函数式更新
  useEffect(() => {
    const timer = setInterval(() => {
      setCount(prev => prev + 1); // 使用最新值
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // 正确：添加依赖
  useEffect(() => {
    document.title = `Count: ${count}`;
  }, [count]); // count变化时重新执行
}

// 自定义Hook复用逻辑
function useDebounce(value, delay) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);
  return debounced;
}
